func (mmPatchTenant *mAdminTenantUseCaseMockPatchTenant) invocationsDone() bool {
	if len(mmPatchTenant.expectations) == 0 && mmPatchTenant.defaultExpectation == nil && mmPatchTenant.mock.funcPatchTenant == nil {
		return true
	}

	totalInvocations := mm_atomic.LoadUint64(&mmPatchTenant.mock.afterPatchTenantCounter)
	expectedInvocations := mm_atomic.LoadUint64(&mmPatchTenant.expectedInvocations)

	return totalInvocations > 0 && (expectedInvocations == 0 || expectedInvocations == totalInvocations)
}

// PatchTenant implements mm_port.AdminTenantUseCase
func (mmPatchTenant *AdminTenantUseCaseMock) PatchTenant(ctx context.Context, cmd mm_port.PatchTenantCommand) (err error) {
	mm_atomic.AddUint64(&mmPatchTenant.beforePatchTenantCounter, 1)
	defer mm_atomic.AddUint64(&mmPatchTenant.afterPatchTenantCounter, 1)

	mmPatchTenant.t.Helper()

	if mmPatchTenant.inspectFuncPatchTenant != nil {
		mmPatchTenant.inspectFuncPatchTenant(ctx, cmd)
	}

	mm_params := AdminTenantUseCaseMockPatchTenantParams{ctx, cmd}

	// Record call args
	mmPatchTenant.PatchTenantMock.mutex.Lock()
	mmPatchTenant.PatchTenantMock.callArgs = append(mmPatchTenant.PatchTenantMock.callArgs, &mm_params)
	mmPatchTenant.PatchTenantMock.mutex.Unlock()

	for _, e := range mmPatchTenant.PatchTenantMock.expectations {
		if minimock.Equal(*e.params, mm_params) {
			mm_atomic.AddUint64(&e.Counter, 1)
			return e.results.err
		}
	}

	if mmPatchTenant.PatchTenantMock.defaultExpectation != nil {
		mm_atomic.AddUint64(&mmPatchTenant.PatchTenantMock.defaultExpectation.Counter, 1)
		mm_want := mmPatchTenant.PatchTenantMock.defaultExpectation.params
		mm_want_ptrs := mmPatchTenant.PatchTenantMock.defaultExpectation.paramPtrs

		mm_got := AdminTenantUseCaseMockPatchTenantParams{ctx, cmd}

		if mm_want_ptrs != nil {

			if mm_want_ptrs.ctx != nil && !minimock.Equal(*mm_want_ptrs.ctx, mm_got.ctx) {
				mmPatchTenant.t.Errorf("AdminTenantUseCaseMock.PatchTenant got unexpected parameter ctx, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmPatchTenant.PatchTenantMock.defaultExpectation.expectationOrigins.originCtx, *mm_want_ptrs.ctx, mm_got.ctx, minimock.Diff(*mm_want_ptrs.ctx, mm_got.ctx))
			}

			if mm_want_ptrs.cmd != nil && !minimock.Equal(*mm_want_ptrs.cmd, mm_got.cmd) {
				mmPatchTenant.t.Errorf("AdminTenantUseCaseMock.PatchTenant got unexpected parameter cmd, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmPatchTenant.PatchTenantMock.defaultExpectation.expectationOrigins.originCmd, *mm_want_ptrs.cmd, mm_got.cmd, minimock.Diff(*mm_want_ptrs.cmd, mm_got.cmd))
			}

		} else if mm_want != nil && !minimock.Equal(*mm_want, mm_got) {
			mmPatchTenant.t.Errorf("AdminTenantUseCaseMock.PatchTenant got unexpected parameters, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
				mmPatchTenant.PatchTenantMock.defaultExpectation.expectationOrigins.origin, *mm_want, mm_got, minimock.Diff(*mm_want, mm_got))
		}

		mm_results := mmPatchTenant.PatchTenantMock.defaultExpectation.results
		if mm_results == nil {
			mmPatchTenant.t.Fatal("No results are set for the AdminTenantUseCaseMock.PatchTenant")
		}
		return (*mm_results).err
	}
	if mmPatchTenant.funcPatchTenant != nil {
		return mmPatchTenant.funcPatchTenant(ctx, cmd)
	}
	mmPatchTenant.t.Fatalf("Unexpected call to AdminTenantUseCaseMock.PatchTenant. %v %v", ctx, cmd)
	return
}

// PatchTenantAfterCounter returns a count of finished AdminTenantUseCaseMock.PatchTenant invocations
func (mmPatchTenant *AdminTenantUseCaseMock) PatchTenantAfterCounter() uint64 {
	return mm_atomic.LoadUint64(&mmPatchTenant.afterPatchTenantCounter)
}

// PatchTenantBeforeCounter returns a count of AdminTenantUseCaseMock.PatchTenant invocations
func (mmPatchTenant *AdminTenantUseCaseMock) PatchTenantBeforeCounter() uint64 {
	return mm_atomic.LoadUint64(&mmPatchTenant.beforePatchTenantCounter)
}

// Calls returns a list of arguments used in each call to AdminTenantUseCaseMock.PatchTenant.
// The list is in the same order as the calls were made (i.e. recent calls have a higher index)
func (mmPatchTenant *mAdminTenantUseCaseMockPatchTenant) Calls() []*AdminTenantUseCaseMockPatchTenantParams {
	mmPatchTenant.mutex.RLock()

	argCopy := make([]*AdminTenantUseCaseMockPatchTenantParams, len(mmPatchTenant.callArgs))
	copy(argCopy, mmPatchTenant.callArgs)

	mmPatchTenant.mutex.RUnlock()

	return argCopy
}

// MinimockPatchTenantDone returns true if the count of the PatchTenant invocations corresponds
// the number of defined expectations
func (m *AdminTenantUseCaseMock) MinimockPatchTenantDone() bool {
	if m.PatchTenantMock.optional {
		// Optional methods provide '0 or more' call count restriction.
		return true
	}

	for _, e := range m.PatchTenantMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			return false
		}
	}

	return m.PatchTenantMock.invocationsDone()
}

// MinimockPatchTenantInspect logs each unmet expectation
func (m *AdminTenantUseCaseMock) MinimockPatchTenantInspect() {
	for _, e := range m.PatchTenantMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			m.t.Errorf("Expected call to AdminTenantUseCaseMock.PatchTenant at\n%s with params: %#v", e.expectationOrigins.origin, *e.params)
		}
	}

	afterPatchTenantCounter := mm_atomic.LoadUint64(&m.afterPatchTenantCounter)
	// if default expectation was set then invocations count should be greater than zero
	if m.PatchTenantMock.defaultExpectation != nil && afterPatchTenantCounter < 1 {
		if m.PatchTenantMock.defaultExpectation.params == nil {
			m.t.Errorf("Expected call to AdminTenantUseCaseMock.PatchTenant at\n%s", m.PatchTenantMock.defaultExpectation.returnOrigin)
		} else {
			m.t.Errorf("Expected call to AdminTenantUseCaseMock.PatchTenant at\n%s with params: %#v", m.PatchTenantMock.defaultExpectation.expectationOrigins.origin, *m.PatchTenantMock.defaultExpectation.params)
		}
	}
	// if func was set then invocations count should be greater than zero
	if m.funcPatchTenant != nil && afterPatchTenantCounter < 1 {
		m.t.Errorf("Expected call to AdminTenantUseCaseMock.PatchTenant at\n%s", m.funcPatchTenantOrigin)
	}

	if !m.PatchTenantMock.invocationsDone() && afterPatchTenantCounter > 0 {
		m.t.Errorf("Expected %d calls to AdminTenantUseCaseMock.PatchTenant at\n%s but found %d calls",
			mm_atomic.LoadUint64(&m.PatchTenantMock.expectedInvocations), m.PatchTenantMock.expectedInvocationsOrigin, afterPatchTenantCounter)
	}
}

// MinimockFinish checks that all mocked methods have been called the expected number of times
func (m *AdminTenantUseCaseMock) MinimockFinish() {
	m.finishOnce.Do(func() {
		if !m.minimockDone() {
			m.MinimockCreateTenantInspect()

			m.MinimockDeleteTenantInspect()

			m.MinimockGetTenantInspect()

			m.MinimockListTenantsInspect()

			m.MinimockPatchTenantInspect()
		}
	})
}

// MinimockWait waits for all mocked methods to be called the expected number of times
func (m *AdminTenantUseCaseMock) MinimockWait(timeout mm_time.Duration) {
	timeoutCh := mm_time.After(timeout)
	for {
		if m.minimockDone() {
			return
		}
		select {
		case <-timeoutCh:
			m.MinimockFinish()
			return
		case <-mm_time.After(10 * mm_time.Millisecond):
		}
	}
}

func (m *AdminTenantUseCaseMock) minimockDone() bool {
	done := true
	return done &&
		m.MinimockCreateTenantDone() &&
		m.MinimockDeleteTenantDone() &&
		m.MinimockGetTenantDone() &&
		m.MinimockListTenantsDone() &&
		m.MinimockPatchTenantDone()
}
